package spola.codegen;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.ByteBuffer;
import java.nio.charset.CharacterCodingException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Optional;
import java.util.regex.Pattern;
import java.util.stream.Stream;

/**
 * Generated files on disk: writing one, finding them, checking that each still matches its
 * record and regenerating them.
 *
 * <p>A generated file is recognized only by its first line, which starts with {@value #MARKER}
 * (see {@link #header(String, String)}); its file name and place play no part in finding it.
 * The header names the record's source file (in the same directory) and the record, so a
 * generated file can be generated again in memory and compared with what is on disk, character
 * for character. A file whose header was removed is no longer a generated file; it is then
 * ordinary source code.
 */
public final class GeneratedFiles {

    /** The start of the first line of every generated file. */
    public static final String MARKER = "// Generated by spola.codegen";

    /** The command, run in {@code framework/}, that regenerates every generated file. */
    public static final String REGENERATE = "java Build.java codegen";

    private static final Pattern HEADER = Pattern.compile(
            Pattern.quote(MARKER) + " from ([^\\s/\\\\]+\\.java), record (\\S+)\\. Do not edit\\.");

    private GeneratedFiles() {
    }

    /**
     * The two header lines every generated file starts with, each ended by {@code \n}:
     * <pre>
     * // Generated by spola.codegen from Person.java, record Person. Do not edit.
     * // Regenerate after changing the record: java Build.java codegen (in framework/)
     * </pre>
     *
     * @param sourceFileName the name of the record's source file, e.g. {@code Person.java}
     * @param recordName the record's name within its package
     * @return the header
     */
    public static String header(String sourceFileName, String recordName) {
        return MARKER + " from " + sourceFileName + ", record " + recordName + ". Do not edit.\n"
                + "// Regenerate after changing the record: " + REGENERATE + " (in framework/)\n";
    }

    /**
     * A generated file that is wrong, or cannot be generated again.
     *
     * @param file the generated file
     * @param message what is wrong and what to do about it
     */
    public record Problem(Path file, String message) {

        /** {@code <file>: <message>}. */
        @Override
        public String toString() {
            return file + ": " + message;
        }
    }

    /**
     * A generated file that was written, or that already had the right content.
     *
     * @param file the generated file
     * @param changed whether the file was created or its content changed
     * @param note a note when the record does not implement the generated interface yet, with
     *     what to add
     */
    public record Written(Path file, boolean changed, Optional<String> note) {
    }

    /**
     * The result of {@link #regenerate(List)}.
     *
     * @param files every generated file that could be generated again, changed or not
     * @param problems every generated file that could not
     */
    public record Regeneration(List<Written> files, List<Problem> problems) {

        /**
         * Copies the lists.
         *
         * @param files the files
         * @param problems the problems
         */
        public Regeneration {
            files = List.copyOf(files);
            problems = List.copyOf(problems);
        }
    }

    /**
     * Generates the with-interface of a record and writes it to
     * {@link RecordCodegen#targetFile(Path, String)}, unless the file already has exactly that
     * content. Works also when the record does not implement the interface yet; the result then
     * carries a note that says what to add.
     *
     * @param sourceFile the record's source file
     * @param recordName the record's name within its package
     * @return the written file
     * @throws CodegenException as {@link RecordCodegen#generate(Path, String)}, or if the target
     *     file exists and is not the generated file of this record (a hand-written file, or the
     *     generated file of another record), which is never overwritten
     * @throws UncheckedIOException if the file cannot be read or written
     */
    public static Written write(Path sourceFile, String recordName) {
        var generation = RecordCodegen.generation(sourceFile, recordName);
        var target = RecordCodegen.targetFile(sourceFile, recordName);
        if (Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
            if (!Files.isRegularFile(target, LinkOption.NOFOLLOW_LINKS)) {
                throw CodegenException.of(sourceFile, recordName, target + " exists and is not a regular file; not overwritten");
            }
            if (!isGenerated(target)) {
                throw CodegenException.of(sourceFile, recordName, target + " exists and is not a generated file"
                        + " (its first line is not the spola.codegen header); not overwritten, rename or remove it");
            }
            String existing;
            try {
                existing = read(target);
            } catch (CharacterCodingException e) {
                existing = "";
            }
            var header = parseHeader(existing);
            var sourceName = String.valueOf(sourceFile.getFileName());
            if (header.isPresent() && !header.get().equals(new Header(sourceName, recordName))) {
                throw CodegenException.of(sourceFile, recordName, target + " is the generated file of record "
                        + header.get().recordName() + " in " + header.get().sourceFileName() + "; not overwritten");
            }
            if (existing.equals(generation.source())) {
                return new Written(target, false, generation.note());
            }
        }
        try {
            Files.writeString(target, generation.source(), StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new UncheckedIOException("cannot write " + target, e);
        }
        return new Written(target, true, generation.note());
    }

    /**
     * Every generated file below the given directories, sorted by path. Does not follow
     * symbolic links.
     *
     * @param roots the directories to search, e.g. the source and test directories of each module
     * @return the generated files
     * @throws UncheckedIOException if a directory cannot be read
     */
    public static List<Path> find(List<Path> roots) {
        var found = new ArrayList<Path>();
        for (var root : roots) {
            if (!Files.isDirectory(root, LinkOption.NOFOLLOW_LINKS)) {
                continue;
            }
            try (Stream<Path> files = Files.walk(root)) {
                for (var file : files.sorted().toList()) {
                    if (file.toString().endsWith(".java") && Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)
                            && isGenerated(file)) {
                        found.add(file);
                    }
                }
            } catch (IOException e) {
                throw new UncheckedIOException("cannot search " + root, e);
            }
        }
        return found;
    }

    /**
     * Checks every generated file below the given directories: generates it again in memory and
     * compares it with the file, character for character. Reads the records' source files only;
     * nothing is compiled, so the check works also when a stale generated file no longer
     * compiles.
     *
     * <p>A problem is reported when the header is damaged, the file is not named after the
     * record in its header, the record's source file is gone, the record can no longer be
     * generated (it was renamed or got a clashing component), the content differs (the record
     * changed or the file was edited by hand), or the record does not implement the generated
     * interface.
     *
     * @param roots the directories to search
     * @return the problems, one per generated file at most; empty if every file is up to date
     * @throws UncheckedIOException if a directory or file cannot be read
     */
    public static List<Problem> check(List<Path> roots) {
        var problems = new ArrayList<Problem>();
        for (var file : find(roots)) {
            switch (inspect(file)) {
                case Broken(var problem) -> problems.add(problem);
                case Expected(var generation, var actual) -> {
                    if (!actual.equals(generation.source())) {
                        problems.add(new Problem(file, "out of date: it no longer matches its record (the record"
                                + " changed, or this file was edited by hand); "
                                + firstDifference(generation.source(), actual) + ". Regenerate it with: " + REGENERATE));
                    } else if (generation.note().isPresent()) {
                        problems.add(new Problem(file, generation.note().get()));
                    }
                }
            }
        }
        return problems;
    }

    /**
     * Generates every generated file below the given directories again and writes those whose
     * content changed. A file that cannot be generated again is left as it is and reported.
     *
     * @param roots the directories to search
     * @return the files and the problems
     * @throws UncheckedIOException if a directory or file cannot be read or written
     */
    public static Regeneration regenerate(List<Path> roots) {
        var files = new ArrayList<Written>();
        var problems = new ArrayList<Problem>();
        for (var file : find(roots)) {
            switch (inspect(file)) {
                case Broken(var problem) -> problems.add(problem);
                case Expected(var generation, var actual) -> {
                    var changed = !actual.equals(generation.source());
                    if (changed) {
                        try {
                            Files.writeString(file, generation.source(), StandardCharsets.UTF_8);
                        } catch (IOException e) {
                            throw new UncheckedIOException("cannot write " + file, e);
                        }
                    }
                    files.add(new Written(file, changed, generation.note()));
                }
            }
        }
        return new Regeneration(files, problems);
    }

    /** The record a header names. */
    private record Header(String sourceFileName, String recordName) {
    }

    /** What a generated file should contain and what it does, or why that cannot be known. */
    private sealed interface Inspection permits Broken, Expected {
    }

    private record Broken(Problem problem) implements Inspection {
    }

    private record Expected(RecordCodegen.Generation generation, String actual) implements Inspection {
    }

    /** What {@code file} (a generated file) should contain, or the problem that prevents knowing it. */
    private static Inspection inspect(Path file) {
        String actual;
        try {
            actual = read(file);
        } catch (CharacterCodingException e) {
            return broken(file, "not valid UTF-8, so it was edited by hand; regenerate it with: " + REGENERATE);
        }
        var header = parseHeader(actual);
        if (header.isEmpty()) {
            return broken(file, "the spola.codegen header on its first line is damaged; restore it to "
                    + header("<Record>.java", "<Record>").lines().findFirst().orElseThrow()
                    + " and regenerate with: " + REGENERATE);
        }
        var source = file.resolveSibling(header.get().sourceFileName());
        var recordName = header.get().recordName();
        var expectedName = RecordCodegen.interfaceName(recordName) + ".java";
        if (!String.valueOf(file.getFileName()).equals(expectedName)) {
            return broken(file, "its header says it is the generated file of record " + recordName + " in "
                    + header.get().sourceFileName() + ", whose generated file is " + expectedName
                    + "; remove this file and run: " + REGENERATE + " " + source + " " + recordName);
        }
        if (!Files.isRegularFile(source)) {
            return broken(file, "the source file " + source + " of its record " + recordName
                    + " does not exist; remove this file if the record is gone");
        }
        try {
            return new Expected(RecordCodegen.generation(source, recordName), actual);
        } catch (CodegenException e) {
            return broken(file, "cannot be regenerated: " + e.getMessage());
        }
    }

    private static Broken broken(Path file, String message) {
        return new Broken(new Problem(file, message));
    }

    private static Optional<Header> parseHeader(String content) {
        var firstLine = content.lines().findFirst().orElse("");
        var matcher = HEADER.matcher(firstLine);
        return matcher.matches() ? Optional.of(new Header(matcher.group(1), matcher.group(2))) : Optional.empty();
    }

    /** Whether the file's first bytes are {@link #MARKER}; reads only those bytes. */
    private static boolean isGenerated(Path file) {
        var marker = MARKER.getBytes(StandardCharsets.US_ASCII);
        try (var in = Files.newInputStream(file)) {
            return Arrays.equals(in.readNBytes(marker.length), marker);
        } catch (IOException e) {
            throw new UncheckedIOException("cannot read " + file, e);
        }
    }

    private static String read(Path file) throws CharacterCodingException {
        try {
            var bytes = Files.readAllBytes(file);
            return StandardCharsets.UTF_8.newDecoder().decode(ByteBuffer.wrap(bytes)).toString();
        } catch (CharacterCodingException e) {
            throw e;
        } catch (IOException e) {
            throw new UncheckedIOException("cannot read " + file, e);
        }
    }

    /** {@code first difference at line 12: expected "...", found "..."}; control characters (a {@code \r}) are escaped. */
    private static String firstDifference(String expected, String actual) {
        var expectedLines = expected.split("(?<=\n)", -1);
        var actualLines = actual.split("(?<=\n)", -1);
        var i = 0;
        while (i < expectedLines.length && i < actualLines.length && expectedLines[i].equals(actualLines[i])) {
            i++;
        }
        return "first difference at line " + (i + 1) + ": expected " + shown(expectedLines, i)
                + ", found " + shown(actualLines, i);
    }

    private static String shown(String[] lines, int index) {
        if (index >= lines.length || lines[index].isEmpty()) {
            return "the end of the file";
        }
        if (lines[index].equals("\n")) {
            return "an empty line";
        }
        var line = lines[index].endsWith("\n") ? lines[index].substring(0, lines[index].length() - 1) : lines[index];
        var text = new StringBuilder("\"");
        line.codePoints().limit(100).forEach(c -> {
            switch (c) {
                case '\n' -> text.append("\\n");
                case '\r' -> text.append("\\r");
                case '\t' -> text.append("\\t");
                default -> {
                    if (Character.isISOControl(c) || !Character.isDefined(c) || Character.getType(c) == Character.FORMAT) {
                        text.append(String.format("\\u%04x", c));
                    } else {
                        text.appendCodePoint(c);
                    }
                }
            }
        });
        if (line.codePointCount(0, line.length()) > 100) {
            text.append("...");
        }
        return text.append('"').toString();
    }
}
